    /// <summary>
    ///MET_5013_ExciseRegisterEntry check for bondnumber 
    /// </summary>
    /// <param name="args">
    /// get the table buffer 
    /// </param>
    [PostHandlerFor(tableStr(InventSite), tableMethodStr(InventSite, validateWrite))]
    public static void InventSite_Post_validateWrite(XppPrePostArgs args)
    {
        InventSite inventSite = args.getThis();

        if(inventSite.METBondedWarehouse == NoYes::Yes && inventSite.METBondNumber == '' )
        {
            checkFailed("@MET:BondNumberIsMandatory");
        }
    }

    /// <summary>
    /// MPJ_21275_BackOrders
    /// Modify based on the user selected back order on item master level and it will give an info
    /// </summary>
    /// <param name="sender">form datasource</param>
    /// <param name="e">Data field</param>
    [
        FormDataFieldEventHandler(formDataFieldStr(InventSite, InventSite, METAllowBackOrders), FormDataFieldEventType::Modified),
        SuppressBPWarningAttribute('BPParameterNotUsed', "@MET:BPParameterNotUsedMessage")
    ]
    public static void METAllowBackOrders_OnModified(FormDataObject sender, FormDataFieldEventArgs e)
    {
        FormDataSource  inventSite_ds   = sender.datasource();
        InventSite      inventSite      = inventSite_ds.cursor();
        DialogButton    dialogButton;
        
        if (inventSite.METAllowBackOrders == NoYes::No)
        {
            dialogButton = Box::yesNo("@MET:METSiteDisableBackOrder", DialogButton::Yes);
            
            if (dialogButton == DialogButton::No)
            {
                inventSite.METAllowBackOrders = NoYes::Yes;
            }
            else
            {
                inventSite.METAllowBackOrders = NoYes::No;
            }
        }

        else if (inventSite.METAllowBackOrders == NoYes::Yes)
        {
            dialogButton = Box::yesNo("@MET:METSiteActivateBackOrder", DialogButton::Yes);
            
            if (dialogButton == DialogButton::No)
            {
                inventSite.METAllowBackOrders = NoYes::No;
            }
            else
            {
                inventSite.METAllowBackOrders = NoYes::Yes;
            }
        }
    }
